dhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Kaveri River","river_distance_km":null,"best_season_notes":null,"submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-11-04T09:54:32.209521+00:00","updated_at":"2026-11-04T12:15:35.665826+00:00","sthala_purana":"Consecrated in 1258 CE by Somanatha Dandanayaka, a general of the Hoysala king Narasimha III, on the banks of the Kaveri about 38 km east of Mysuru. The ornate temple stands on a high star-shaped platform with three symmetrical sanctums around a shared pillared hall: the western for Kesava (the image is missing), the northern for Janardhana and the southern for Venugopala. A pillared corridor of small shrines (damaged) encloses the courtyard, and the walls, pillars and ceilings carry dense carved iconography.","etiquette_notes":null,"native_name":null,"morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Mysore Mandakalli Airport","nearest_airport_distance_km":25.5,"nearest_railway_station_name":"Kadakola railway station","nearest_railway_distance_km":25.5,"emergency_contact_notes":null,"sthala_purana_source":"Wikipedia (Chennakesava Temple, Somanathapura)","architecture_style":"Hoysala; trikuta (three-sanctum) plan on a star-shaped platform","construction_century":13},{"id":"b1820653-350a-47d4-833b-8533a5a4c615","name":"Lalguan Mahadeva Temple","deity":"Shiva as Mahadeva","sampradaya":"Shaiva","significance":[],"country":"India","state":"Madhya Pradesh","district":"Chhatarpur","town":"Khajuraho","latitude":24.8508,"longitude":79.91127,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name"