gle classical Sanskrit text","architecture_style":null,"construction_century":20},{"id":"b93a568d-f363-48b4-861d-653121fed67b","name":"Tapkeshwar Temple","deity":"Shiva as Tapkeshwar Mahadev","sampradaya":"Shaiva","significance":[],"country":"India","state":"Uttarakhand","district":"Dehradun","town":"Chandmari","latitude":30.35727,"longitude":78.01668,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Tons River","river_distance_km":null,"best_season_notes":null,"submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-11-04T11:38:01.041713+00:00","updated_at":"2026-11-04T12:15:00.624755+00:00","sthala_purana":"A Shiva temple in Dehradun on the bank of the Tons River. It is built over a natural cave that holds the main shivalinga.","etiquette_notes":null,"native_name":null,"morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Dehradun Airport","nearest_airport_distance_km":24.2,"nearest_railway_station_name":"Dehradun railway station","nearest_railway_distance_km":5,"emergency_contact_notes":null,"sthala_purana_source":"Wikipedia (Tapkeshwar Temple), summarised; location via OpenStreetMap","architecture_style":null,"construction_century":null},{"id":"b95a3d9a-e771-4759-9d60-28b30d725d32","name":"Ujjaini Mahakali Temple, Secunderabad","deity":"Mahakali (Devi)","sampradaya":"Shakta","significance":["Bonalu"],"country":"India","state":"Telangana","district":"Hyderabad","town":"Secunderabad","latitude":17.436678,"longitude":78.491074,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Musi River","river_distance_km":5.7,"best_season_notes":"Its Bonalu (Ashada Jatara), typically in the Hindu month of Ashada around July, is one of the most prominent in Hyderabad/Secunderabad.","submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-09-22T08:36:33.433509+00:00","updated_at":"2026-11-05T02:38:03.965515+00:00","sthala_purana":"Founded after a cholera outbreak in 1813 that coincided with the transfer of military battalions from Secunderabad to Ujjain. A doli-bearer, Suriti Appaiah, travelled to the Mahakali Devasthanam at Ujjain with his associates and vowed to install an idol if the epidemic relented; a wooden idol was installed in Secunderabad in July 1814, with the temple structure completed around 1815. It has since become one of the principal centres of the annual Bonalu festival, when devotees — especially women carrying \"bonam\" offerings — gather here in large numbers.","etiquette_notes":null,"native_name":null,"morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Begumpet Airport","nearest_airport_distance_km":3.1,"nearest_railway_station_name":"James Street railway station","nearest_railway_distance_km":0.6,"emergency_contact_notes":null,"sthala_purana_source":"Temple history as documented in regional press and municipal heritage records","architecture_style":null,"construction_century":19},{"id":"b9c88574-6795-4885-90b1-3f657703b297","name":"Virbhadra Temple","deity":"Shiva as Virbhadra","sampradaya":"Shaiva","significance":[],"country":"India","state":"Uttarakhand","district":"Dehradun","town":"Barrage","latitude":30.06753,"longitude":78.28008,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_ri