umbhari Devi, Saharanpur","deity":"Shakumbhari Devi","sampradaya":"Shakta","significance":[],"country":"India","state":"Uttar Pradesh","district":"Saharanpur","town":"Behat","latitude":30.2566,"longitude":77.7425,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Tons Nadi River","river_distance_km":13.8,"best_season_notes":null,"submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-11-04T11:04:44.755986+00:00","updated_at":"2026-11-05T02:38:03.965515+00:00","sthala_purana":"A Hindu temple in the Shivalik Hills near Jasmour village in Behat tehsil, roughly 40 km north of Saharanpur. It honours Shakumbhari, a form of Parvati linked with nourishment, vegetation and fertility. It is a major pilgrimage centre of northern India, with Navratri and Diwali as the main festivals.","etiquette_notes":null,"native_name":null,"morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Sarsawa Air Force Station","nearest_airport_distance_km":42.1,"nearest_railway_station_name":"Dehradun railway station","nearest_railway_distance_km":28.7,"emergency_contact_notes":null,"sthala_purana_source":"Wikipedia (Siddhpeeth Shri Shakumbhari Devi, Saharanpur), summarised; location via OpenStreetMap","architecture_style":null,"construction_century":null},{"id":"c356c10a-014b-4c45-993b-92104893a536","name":"Aliganj Hanuman Temple","deity":"Hanuman","sampradaya":"Vaishnava","significance":[],"country":"India","state":"Uttar Pradesh","district":"Lucknow","town":"Lucknow","latitude":26.88387,"longitude":80.95037,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,