ted image of Shiva in the form of Damodar.","etiquette_notes":null,"native_name":null,"morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Goa International Airport","nearest_airport_distance_km":35.4,"nearest_railway_station_name":"Sanvordem Curchorem railway station","nearest_railway_distance_km":8.7,"emergency_contact_notes":null,"sthala_purana_source":"Wikipedia (Damodar Sansthaan), summarised; location via OpenStreetMap","architecture_style":null,"construction_century":null},{"id":"c8fd53fc-ba66-4ebb-9422-68a360fc9754","name":"Bhadrakali Temple, Warangal","deity":"Bhadrakali","sampradaya":"Shakta","significance":[],"country":"India","state":"Telangana","district":"Warangal","town":"Warangal","latitude":17.995,"longitude":79.5828,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":null,"river_distance_km":null,"best_season_notes":null,"submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-09-30T13:17:24.643882+00:00","updated_at":"2026-11-04T12:15:00.624755+00:00","sthala_purana":"Traditionally dated to 625 CE and said to have been built by the Chalukya king Pulakeshin II to commemorate a military victory; the Kakatiya dynasty later adopted the goddess as their kuladevata (family deity). The square stone image, about 2.7 m across, has eight arms. An adjacent lake was built by the Kakatiya king Ganapati-deva; the temple itself was renovated in 1950.","etiquette_notes":null,"native_name":null,"morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Warangal Airport","nearest_airport_distance_km":9.3,"nearest_railway_sta